transfer.sketch:
-- controls: 800 lawyer labels, ~40 per class after stratification (note 4, note 9)
-- note: these labels are then unavailable as training data; budget them deliberately

gate(c) -> keep | unknown            -- partial: only classes with a cheap measured rule
  if c.kind == renewal and not mentions(c, definedTerm("Renewal Term")): return unknown
  return keep                        -- classes with no rule pass through ungated

batch = shuffle(realClauses ++ sample(controlsPos[c], 20) ++ sample(controlsNeg[c], 20))
runs  = chunks(batch, 6)

score(verdicts, controls) -> { auc, accuracyAt05, brier, hi[c], lo[c], usableShare }
  hi[c] = lowest p where precision(label = c | p >= hi) on controls >= targetPrecision[c]

for v in verdicts of real clauses:
  if v.p >= hi[v.topClass] and noSecondAcceptedClass: accept(v.id, v.topClass)
  elif v.p <= lo[v.topClass]:                         accept(v.id, not v.topClass)
  else: review.enqueue(v.id, rank: |v.p - hi[v.topClass]|, showVerdict: false)

review.take(first: 3000 by rank)          -- the rest stay unknown, never accepted
for v in randomSample(accepted, n ~ 100): review.enqueue(v.id, showVerdict: false)   -- audit
for c in controls where agreeCount(judges, against: c.truth, p > 0.8) >= 2:
  review.enqueue(c.id, showVerdict: false, reason: "control under doubt")
